        8 -> d_field_StopResult_ok(Rest, 0, 0, 0, F@_1, TrUserData);
        _ ->
            case Key band 7 of
                0 -> skip_varint_StopResult(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                1 -> skip_64_StopResult(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                2 -> skip_length_delimited_StopResult(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                3 -> skip_group_StopResult(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                5 -> skip_32_StopResult(Rest, 0, 0, Key bsr 3, F@_1, TrUserData)
            end
    end;
dg_read_field_def_StopResult(<<>>, 0, 0, _, F@_1, _) -> #{ok => F@_1}.

d_field_StopResult_ok(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) when N < 57 -> d_field_StopResult_ok(Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData);
