-compile({nowarn_unused_function,merge_msg_PanelFrame/3}).
merge_msg_PanelFrame(PMsg, NMsg, TrUserData) ->
    S1 = #{},
    case {PMsg, NMsg} of
        {#{request := PFrequest}, #{request := NFrequest}} -> S1#{request => merge_msg_PanelRequest(PFrequest, NFrequest, TrUserData)};
        {#{response := PFresponse}, #{response := NFresponse}} -> S1#{response => merge_msg_PanelResponse(PFresponse, NFresponse, TrUserData)};
        {#{stream := PFstream}, #{stream := NFstream}} -> S1#{stream => merge_msg_PanelStream(PFstream, NFstream, TrUserData)};
        {#{exec := PFexec}, #{exec := NFexec}} -> S1#{exec => merge_msg_PanelExec(PFexec, NFexec, TrUserData)};
        {#{exec_result := PFexec_result}, #{exec_result := NFexec_result}} -> S1#{exec_result => merge_msg_PanelExecResult(PFexec_result, NFexec_result, TrUserData)};
        {_, #{request := NFrequest}} -> S1#{request => NFrequest};
        {_, #{response := NFresponse}} -> S1#{response => NFresponse};
        {_, #{stream := NFstream}} -> S1#{stream => NFstream};
        {_, #{exec := NFexec}} -> S1#{exec => NFexec};
        {_, #{exec_result := NFexec_result}} -> S1#{exec_result => NFexec_result};
        {#{request := PFrequest}, _} -> S1#{request => PFrequest};
        {#{response := PFresponse}, _} -> S1#{response => PFresponse};
        {#{stream := PFstream}, _} -> S1#{stream => PFstream};
        {#{exec := PFexec}, _} -> S1#{exec => PFexec};
        {#{exec_result := PFexec_result}, _} -> S1#{exec_result => PFexec_result};
        _ -> S1
    end.

-compile({nowarn_unused_function,merge_msg_PanelExec/3}).
merge_msg_PanelExec(PMsg, NMsg, _) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
             {_, #{id := NFid}} -> S1#{id => NFid};
             {#{id := PFid}, _} -> S1#{id => PFid};
             _ -> S1
         end,
    case {PMsg, NMsg} of
        {_, #{agent_request := NFagent_request}} -> S2#{agent_request => NFagent_request};
        {#{agent_request := PFagent_request}, _} -> S2#{agent_request => PFagent_request};
        _ -> S2
    end.

-compile({nowarn_unused_function,merge_msg_PanelExecResult/3}).
merge_msg_PanelExecResult(PMsg, NMsg, _) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
             {_, #{id := NFid}} -> S1#{id => NFid};
             {#{id := PFid}, _} -> S1#{id => PFid};
             _ -> S1
         end,
    S3 = case {PMsg, NMsg} of
             {_, #{agent_response := NFagent_response}} -> S2#{agent_response => NFagent_response};
             {#{agent_response := PFagent_response}, _} -> S2#{agent_response => PFagent_response};
             _ -> S2
         end,
    S4 = case {PMsg, NMsg} of
             {_, #{error := NFerror}} -> S3#{error => NFerror};
             {#{error := PFerror}, _} -> S3#{error => PFerror};
             _ -> S3
         end,
    case {PMsg, NMsg} of
        {_, #{terminal := NFterminal}} -> S4#{terminal => NFterminal};
        {#{terminal := PFterminal}, _} -> S4#{terminal => PFterminal};
        _ -> S4
    end.

-compile({nowarn_unused_function,merge_msg_PanelRequest/3}).
merge_msg_PanelRequest(PMsg, NMsg, _) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
             {_, #{id := NFid}} -> S1#{id => NFid};
             {#{id := PFid}, _} -> S1#{id => PFid};
             _ -> S1
         end,
    S3 = case {PMsg, NMsg} of
             {_, #{method := NFmethod}} -> S2#{method => NFmethod};
             {#{method := PFmethod}, _} -> S2#{method => PFmethod};
             _ -> S2
         end,
    case {PMsg, NMsg} of
        {_, #{args_bytes := NFargs_bytes}} -> S3#{args_bytes => NFargs_bytes};
        {#{args_bytes := PFargs_bytes}, _} -> S3#{args_bytes => PFargs_bytes};
        _ -> S3
    end.

-compile({nowarn_unused_function,merge_msg_PanelResponse/3}).
merge_msg_PanelResponse(PMsg, NMsg, _) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
             {_, #{id := NFid}} -> S1#{id => NFid};
             {#{id := PFid}, _} -> S1#{id => PFid};
             _ -> S1
         end,
    case {PMsg, NMsg} of
        {_, #{result_bytes := NFresult_bytes}} -> S2#{result_bytes => NFresult_bytes};
        {_, #{error := NFerror}} -> S2#{error => NFerror};
        {#{result_bytes := PFresult_bytes}, _} -> S2#{result_bytes => PFresult_bytes};
        {#{error := PFerror}, _} -> S2#{error => PFerror};
        _ -> S2
    end.

-compile({nowarn_unused_function,merge_msg_PanelStream/3}).
merge_msg_PanelStream(PMsg, NMsg, TrUserData) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
             {_, #{stream_id := NFstream_id}} -> S1#{stream_id => NFstream_id};
             {#{stream_id := PFstream_id}, _} -> S1#{stream_id => PFstream_id};
             _ -> S1
         end,
    case {PMsg, NMsg} of
        {#{chunk := PFchunk}, #{chunk := NFchunk}} -> S2#{chunk => merge_msg_LlmChunk(PFchunk, NFchunk, TrUserData)};
        {#{tool_event := PFtool_event}, #{tool_event := NFtool_event}} -> S2#{tool_event => merge_msg_ToolEvent(PFtool_event, NFtool_event, TrUserData)};
        {#{final := PFfinal}, #{final := NFfinal}} -> S2#{final => merge_msg_FinalAnswer(PFfinal, NFfinal, TrUserData)};
        {#{error := PFerror}, #{error := NFerror}} -> S2#{error => merge_msg_StreamError(PFerror, NFerror, TrUserData)};
        {#{approval_required := PFapproval_required}, #{approval_required := NFapproval_required}} -> S2#{approval_required => merge_msg_ApprovalRequired(PFapproval_required, NFapproval_required, TrUserData)};
        {#{plan_generated := PFplan_generated}, #{plan_generated := NFplan_generated}} -> S2#{plan_generated => merge_msg_PlanGenerated(PFplan_generated, NFplan_generated, TrUserData)};
        {#{plan_step_update := PFplan_step_update}, #{plan_step_update := NFplan_step_update}} -> S2#{plan_step_update => merge_msg_PlanStepUpdate(PFplan_step_update, NFplan_step_update, TrUserData)};
        {_, #{chunk := NFchunk}} -> S2#{chunk => NFchunk};
        {_, #{tool_event := NFtool_event}} -> S2#{tool_event => NFtool_event};
        {_, #{final := NFfinal}} -> S2#{final => NFfinal};
        {_, #{error := NFerror}} -> S2#{error => NFerror};
        {_, #{approval_required := NFapproval_required}} -> S2#{approval_required => NFapproval_required};
        {_, #{plan_generated := NFplan_generated}} -> S2#{plan_generated => NFplan_generated};
        {_, #{plan_step_update := NFplan_step_update}} -> S2#{plan_step_update => NFplan_step_update};
        {#{chunk := PFchunk}, _} -> S2#{chunk => PFchunk};
        {#{tool_event := PFtool_event}, _} -> S2#{tool_event => PFtool_event};
        {#{final := PFfinal}, _} -> S2#{final => PFfinal};
        {#{error := PFerror}, _} -> S2#{error => PFerror};
        {#{approval_required := PFapproval_required}, _} -> S2#{approval_required => PFapproval_required};
        {#{plan_generated := PFplan_generated}, _} -> S2#{plan_generated => PFplan_generated};
        {#{plan_step_update := PFplan_step_update}, _} -> S2#{plan_step_update => PFplan_step_update};
        _ -> S2
    end.

-compile({nowarn_unused_function,merge_msg_ApprovalRequired/3}).
merge_msg_ApprovalRequired(PMsg, NMsg, _) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
